/**
 * SQLite-backed memory store.
 * Three tables:
 * - semantic: key-value facts (preferences, project patterns, corrections)
 * - lessons: learned corrections with dedup
 * - events: audit log of all memory operations
 *
 * Supports both Node ≥22 (node:sqlite / DatabaseSync) and Bun (bun:sqlite / Database).
 * The two APIs have the same synchronous surface; only the import path differs.
 */
import { createRequire } from "node:module";
import { mkdirSync, existsSync } from "node:fs";
import { dirname } from "node:path";
import { cosine, fromBlob } from "./vector.js";

// node:module / createRequire is available in both Node and Bun.
const _require = createRequire(import.meta.url);

// Detect Bun at runtime — it exposes a global `Bun` object.
// eslint-disable-next-line @typescript-eslint/no-explicit-any
const isBun = typeof (globalThis as any).Bun !== "undefined";

/**
 * Synchronous SQLite database constructor.
 * - Node ≥22 : `DatabaseSync` from `node:sqlite`
 * - Bun      : `Database`     from `bun:sqlite`
 *
 * Both expose the same synchronous `prepare / exec / close` surface used below.
 * The only difference in practice: `.get()` returns `null` (Bun) vs `undefined`
 * (Node) for no-row queries — both are falsy, so all callers are unaffected.
 */
// eslint-disable-next-line @typescript-eslint/no-explicit-any
const DatabaseSync: new (path: string) => any = isBun
  ? _require("bun:sqlite").Database
  : _require("node:sqlite").DatabaseSync;

// ─── Types ───────────────────────────────────────────────────────────

export interface SemanticEntry {
  key: string;
  value: string;
  confidence: number;
  source: "user" | "consolidation" | "correction";
  /** Session the fact was extracted from, so a wrong fact can be traced back. */
  session_id?: string | null;
  created_at: string;
  updated_at: string;
  last_accessed?: string;
}

export interface LessonEntry {
  id: string;
  rule: string;
  category: string;
  source: string;
  negative: boolean;
  created_at: string;
  /** Project slug this lesson was extracted from, or null for user-authored / global lessons */
  project: string | null;
}

export interface MemoryEvent {
  id: number;
  event_type: string;
  memory_type: string;
  memory_key: string;
  details: string;
  created_at: string;
}

// ─── Store ───────────────────────────────────────────────────────────

export class MemoryStore {
  private db: InstanceType<typeof DatabaseSync>;
  private writeLock: Promise<void> = Promise.resolve();
  private hasFTS5: boolean = false;
  // Non-zero while a transaction is open, so nested calls join it instead of
  // starting a second BEGIN (which SQLite rejects).
  private txDepth: number = 0;

  constructor(dbPath: string) {
    const dir = dirname(dbPath);
    if (!existsSync(dir)) mkdirSync(dir, { recursive: true });

    this.db = new DatabaseSync(dbPath);
    this.db.exec("PRAGMA journal_mode = WAL");
    // WAL + NORMAL is durable across process crashes; only an OS/power crash can
    // lose the newest commits. FULL costs an fsync per write — ~77 ms on a slow
    // disk, i.e. ~85 ms for a single stored fact — and this store writes in small
    // transactions from the session path.
    this.db.exec("PRAGMA synchronous = NORMAL");
    // Checkpoint in small slices while the session runs instead of letting the
    // WAL grow to the 1000-page default: the deferred cost then lands on some
    // random commit — measured as a 1.3 s stall in the middle of a session —
    // instead of here. 128 pages ≈ 512 KB.
    this.db.exec("PRAGMA wal_autocheckpoint = 128");
    // ...and give the file back once it is checkpointed, instead of keeping a
    // multi-megabyte -wal around from earlier runs.
    this.db.exec("PRAGMA journal_size_limit = 1048576");
    this.db.exec("PRAGMA busy_timeout = 5000");
    this.db.exec("PRAGMA foreign_keys = ON");
    this.migrate();
  }

  private migrate(): void {
    this.db.exec(`
      CREATE TABLE IF NOT EXISTS semantic (
        key TEXT PRIMARY KEY,
        value TEXT NOT NULL,
        confidence REAL NOT NULL DEFAULT 0.8,
        source TEXT NOT NULL DEFAULT 'consolidation',
        created_at TEXT NOT NULL DEFAULT (datetime('now')),
        updated_at TEXT NOT NULL DEFAULT (datetime('now'))
      );

      CREATE TABLE IF NOT EXISTS lessons (
        id TEXT PRIMARY KEY,
        rule TEXT NOT NULL,
        category TEXT NOT NULL DEFAULT 'general',
        source TEXT NOT NULL DEFAULT 'consolidation',
        negative INTEGER NOT NULL DEFAULT 0,
        is_deleted INTEGER NOT NULL DEFAULT 0,
        created_at TEXT NOT NULL DEFAULT (datetime('now'))
      );

      CREATE TABLE IF NOT EXISTS events (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        event_type TEXT NOT NULL,
        memory_type TEXT NOT NULL,
        memory_key TEXT NOT NULL,
        details TEXT NOT NULL DEFAULT '',
        created_at TEXT NOT NULL DEFAULT (datetime('now'))
      );

      -- Durable outbox for session-end consolidation. The session path only
      -- appends here (one commit); the LLM call happens later, off the
      -- interaction path.
      CREATE TABLE IF NOT EXISTS pending_consolidation (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        session_id TEXT,
        user_count INTEGER NOT NULL DEFAULT 0,
        payload TEXT NOT NULL,
        attempts INTEGER NOT NULL DEFAULT 0,
        created_at TEXT NOT NULL DEFAULT (datetime('now')),
        claimed_at TEXT
      );
    `);

    // Migration: the first outbox shipped without session_id/user_count.
    for (const column of [
      "session_id TEXT",
      "user_count INTEGER NOT NULL DEFAULT 0",
      "attempts INTEGER NOT NULL DEFAULT 0",
    ]) {
      try {
        this.db.exec(`ALTER TABLE pending_consolidation ADD COLUMN ${column}`);
      } catch {
        // Column already there.
      }
    }
    // A partial unique index used to enforce "one unclaimed job per session".
    // It was wrong: a drain in flight holds one row while a new tail queues a
    // second, and clearing the claim then violates the index — which made
    // releasePending/failPending throw, so a claim could never be handed back
    // and attempts never reached their cap. Superseding happens in
    // enqueuePending instead, where the two tails can actually be compared.
    this.db.exec(`DROP INDEX IF EXISTS pending_session`);

    // Migration: add last_accessed column if missing
    try {
      this.db.exec(`ALTER TABLE semantic ADD COLUMN last_accessed TEXT`);
    } catch {
      // Column already exists — ignore
    }
    // Migration: record which session a fact came from (provenance)
    try {
      this.db.exec(`ALTER TABLE semantic ADD COLUMN session_id TEXT`);
    } catch {
      // Column already exists — ignore
    }
    // Migration: add project column to lessons if missing
    try {
      this.db.exec(`ALTER TABLE lessons ADD COLUMN project TEXT`);
    } catch {
      // Column already exists — ignore
    }
    // Migration: add embedding column for semantic vector search
    try {
      this.db.exec(`ALTER TABLE semantic ADD COLUMN embedding BLOB`);
    } catch {
      // Column already exists — ignore
    }

    // FTS5 virtual tables for semantic + lesson search (optional — node:sqlite may lack FTS5)
    try {
      this.db.exec(`
        CREATE VIRTUAL TABLE IF NOT EXISTS semantic_fts USING fts5(key, value, content='semantic', content_rowid='rowid');

        CREATE TRIGGER IF NOT EXISTS semantic_ai AFTER INSERT ON semantic BEGIN
          INSERT INTO semantic_fts(rowid, key, value) VALUES (new.rowid, new.key, new.value);
        END;
        CREATE TRIGGER IF NOT EXISTS semantic_ad AFTER DELETE ON semantic BEGIN
          INSERT INTO semantic_fts(semantic_fts, rowid, key, value) VALUES('delete', old.rowid, old.key, old.value);
        END;
        CREATE TRIGGER IF NOT EXISTS semantic_au AFTER UPDATE ON semantic BEGIN
          INSERT INTO semantic_fts(semantic_fts, rowid, key, value) VALUES('delete', old.rowid, old.key, old.value);
          INSERT INTO semantic_fts(rowid, key, value) VALUES (new.rowid, new.key, new.value);
        END;
      `);

      this.db.exec(`
        CREATE VIRTUAL TABLE IF NOT EXISTS lessons_fts USING fts5(rule, category, content='lessons', content_rowid='rowid');

        CREATE TRIGGER IF NOT EXISTS lessons_fts_ai AFTER INSERT ON lessons BEGIN
          INSERT INTO lessons_fts(rowid, rule, category) VALUES (new.rowid, new.rule, new.category);
        END;
        CREATE TRIGGER IF NOT EXISTS lessons_fts_ad AFTER DELETE ON lessons BEGIN
          INSERT INTO lessons_fts(lessons_fts, rowid, rule, category) VALUES('delete', old.rowid, old.rule, old.category);
        END;
        CREATE TRIGGER IF NOT EXISTS lessons_fts_au AFTER UPDATE ON lessons BEGIN
          INSERT INTO lessons_fts(lessons_fts, rowid, rule, category) VALUES('delete', old.rowid, old.rule, old.category);
          INSERT INTO lessons_fts(rowid, rule, category) VALUES (new.rowid, new.rule, new.category);
        END;
      `);

      // Rebuild the FTS indexes only when they are actually out of sync.
      //
      // This runs on every store open — every session_start, /new and /resume —
      // and an unconditional rebuild re-indexes rows the triggers above already
      // keep current; on a machine with slow commits that is the dominant part
      // of store construction. Counting `_docsize` (one row per indexed
      // document) is the cheap way to see a stale index: `COUNT(*)` on an
      // external-content FTS5 table re-reads the content table and therefore
      // always matches, so it cannot detect one.
      let ftsInSync = false;
      try {
        const guard = this.db
          .prepare(
            `SELECT (SELECT COUNT(*) FROM semantic) = (SELECT COUNT(*) FROM semantic_fts_docsize)
                AND (SELECT COUNT(*) FROM lessons) = (SELECT COUNT(*) FROM lessons_fts_docsize) AS ok`,
          )
          // Bun's .get() returns null where Node returns undefined.
          .get() as { ok: number } | null | undefined;
        ftsInSync = !!guard && guard.ok === 1;
      } catch {
        // No `_docsize` shadow table (e.g. columnsize=0) — rebuild to be safe.
        ftsInSync = false;
      }
      if (!ftsInSync) {
        // One transaction: the two rebuilds otherwise commit separately. The
        // rollback is not optional — an open transaction here makes every later
        // BEGIN fail, i.e. the store silently turns read-only for the session.
        this.db.exec("BEGIN");
        try {
          this.db.exec(`INSERT INTO semantic_fts(semantic_fts) VALUES('rebuild')`);
          this.db.exec(`INSERT INTO lessons_fts(lessons_fts) VALUES('rebuild')`);
          this.db.exec("COMMIT");
        } catch (err) {
          try { this.db.exec("ROLLBACK"); } catch { /* transaction already gone */ }
          throw err;
        }
      }
      this.hasFTS5 = true;
    } catch {
      // FTS5 not available (node:sqlite compiled without SQLITE_ENABLE_FTS5).
      // Search will use substring fallback — fine for typical memory store sizes.
      this.hasFTS5 = false;
    }
  }

  /**
   * Serialize async callers so concurrent read-modify-write cycles
   * (e.g. two consolidation calls) don't clobber each other.
   *
   * Re-entrant: a `transaction()` block may call methods that take the lock
   * themselves, which is how writing facts and dropping their queue job stay
   * atomic without every caller knowing about the outer transaction.
   */
  private withLock<T>(fn: () => T): T {
    // Already inside a transaction: the outer commit covers this work.
    if (this.txDepth > 0) return fn();

    // DatabaseSync is synchronous, so we just need to ensure
    // transactional integrity. Wrap in a SQLite transaction.
    this.db.exec("BEGIN IMMEDIATE");
    this.txDepth = 1;
    try {
      const result = fn();
      this.db.exec("COMMIT");
      return result;
    } catch (err) {
      this.db.exec("ROLLBACK");
      throw err;
    } finally {
      this.txDepth = 0;
    }
  }

  /** Run several operations atomically (e.g. write facts and drop their job). */
  transaction<T>(fn: () => T): T {
    return this.withLock(fn);
  }

  // ─── Semantic ────────────────────────────────────────────────────

  getSemantic(key: string): SemanticEntry | undefined {
    const normalized = key.toLowerCase();
    return this.db.prepare("SELECT * FROM semantic WHERE key = ?").get(normalized) as unknown as SemanticEntry | undefined;
  }

  setSemantic(
    key: string,
    value: string,
    confidence: number = 0.8,
    source: SemanticEntry["source"] = "consolidation",
    sessionId?: string,
  ): void {
    const normalized = key.toLowerCase();
    this.withLock(() => {
      const existing = this.db.prepare("SELECT * FROM semantic WHERE key = ?").get(normalized) as unknown as SemanticEntry | undefined;
      if (existing && existing.confidence > confidence) return; // higher confidence wins

      this.db.prepare(`
        INSERT INTO semantic (key, value, confidence, source, session_id, updated_at)
        VALUES (?, ?, ?, ?, ?, datetime('now'))
        ON CONFLICT(key) DO UPDATE SET
          value = excluded.value,
          confidence = excluded.confidence,
          source = excluded.source,
          session_id = COALESCE(excluded.session_id, semantic.session_id),
          -- A changed value invalidates its vector: an embedding of the old
          -- text would keep ranking this fact for queries it no longer
          -- answers. NULL makes the backfill re-embed it.
          embedding = CASE WHEN excluded.value = semantic.value THEN semantic.embedding ELSE NULL END,
          updated_at = datetime('now')
      `).run(normalized, value, confidence, source, sessionId ?? null);

      this.logEvent(existing ? "update" : "create", "semantic", normalized);
    });
  }

  deleteSemantic(key: string): boolean {
    const normalized = key.toLowerCase();
    return this.withLock(() => {
      const result = this.db.prepare("DELETE FROM semantic WHERE key = ?").run(normalized);
      if (result.changes > 0) this.logEvent("delete", "semantic", normalized);
      return result.changes > 0;
    });
  }

  /**
   * Store a pre-computed embedding for a key.
   * Converts Float32Array → Buffer for SQLite BLOB storage.
   */
  setEmbedding(key: string, embedding: Float32Array): void {
    const normalized = key.toLowerCase();
    const blob = Buffer.from(new Uint8Array(embedding.buffer, embedding.byteOffset, embedding.byteLength));
    this.db.prepare("UPDATE semantic SET embedding = ? WHERE key = ?").run(blob, normalized);
  }

  /**
   * Return all semantic keys with their raw embedding BLOBs.
   * Used for in-memory cosine similarity at query time.
   * Entries without an embedding have embedding = null.
   */
  getAllEmbeddings(): Array<{ key: string; embedding: Buffer | null }> {
    return this.db
      .prepare("SELECT key, embedding FROM semantic ORDER BY updated_at DESC")
      .all() as unknown as Array<{ key: string; embedding: Buffer | null }>;
  }

  /**
   * Rank stored entries by cosine similarity against a query vector.
   *
   * Entries without an embedding are skipped rather than scored 0, so a
   * partially-embedded store -- the normal case, since embeddings are written
   * lazily as facts arrive -- does not drag un-embedded entries below lexical
   * results they would have won on merit.
   *
   * `minScore` drops weak matches, so RRF is not handed noise to reward for
   * being "found by two paths".
   *
   * The default is calibrated against amazon.titan-embed-text-v2:0 at 512
   * dimensions, measured rather than assumed:
   *
   *   paraphrases of a stored fact   0.219 - 0.248
   *   loosely related text           0.235
   *   unrelated text                -0.025 - 0.082
   *
   * Titan's usable range is much narrower than raw cosine suggests, so 0.15
   * sits mid-gap with roughly equal margin on both sides. A higher-contrast
   * model may want a higher floor; pass `minScore` explicitly if you change
   * providers.
   */
  searchSemanticByVector(
    queryVector: Float32Array,
    limit: number = 10,
    minScore: number = 0.15,
  ): SemanticEntry[] {
    const scored: Array<{ key: string; score: number }> = [];
    for (const row of this.getAllEmbeddings()) {
      const vec = fromBlob(row.embedding);
      if (!vec) continue;
      const score = cosine(queryVector, vec);
      if (score >= minScore) scored.push({ key: row.key, score });
    }
    if (scored.length === 0) return [];

    scored.sort((a, b) => b.score - a.score);
    const top = scored.slice(0, limit);

    // Re-fetch full rows in one statement, then restore similarity order:
    // SQL `IN (...)` does not preserve the order of its value list.
    const placeholders = top.map(() => "?").join(",");
    const rows = this.db
      .prepare(`SELECT * FROM semantic WHERE key IN (${placeholders})`)
      .all(...top.map((t) => t.key)) as unknown as SemanticEntry[];
    const byKey = new Map(rows.map((r) => [r.key, r]));
    return top
      .map((t) => byKey.get(t.key))
      .filter((r): r is SemanticEntry => r !== undefined);
  }

  /** How much of the store is embedded. Surfaced by memory_stats. */
  embeddingCoverage(): { embedded: number; total: number } {
    const rows = this.getAllEmbeddings();
    return {
      embedded: rows.filter((r) => fromBlob(r.embedding) !== null).length,
      total: rows.length,
    };
  }

  /**
   * Entries needing an embedding: absent, unreadable, or -- when `dimensions`
   * is given -- the wrong width.
   *
   * The width check matters for stores written before #31: that backend used
   * 384-dim MiniLM vectors, while a Bedrock Titan config produces 512. Since
   * cosine() returns 0 for mismatched lengths, a stale-width vector is not
   * merely useless, it is invisible -- and without this check it would never be
   * replaced, because the column is non-null.
   */
  entriesNeedingEmbedding(
    dimensions?: number,
    limit: number = 500,
  ): Array<{ key: string; value: string }> {
    const stale: string[] = [];
    for (const row of this.getAllEmbeddings()) {
      const vec = fromBlob(row.embedding);
      if (vec === null || (dimensions !== undefined && vec.length !== dimensions)) {
        stale.push(row.key);
        if (stale.length >= limit) break;
      }
    }
    if (stale.length === 0) return [];

    const placeholders = stale.map(() => "?").join(",");
    return this.db
      .prepare(`SELECT key, value FROM semantic WHERE key IN (${placeholders})`)
      .all(...stale) as unknown as Array<{ key: string; value: string }>;
  }

  listSemantic(prefix?: string, limit: number = 100): SemanticEntry[] {
    if (prefix) {
      return this.db.prepare("SELECT * FROM semantic WHERE key LIKE ? ORDER BY updated_at DESC LIMIT ?")
        .all(`${prefix}%`, limit) as unknown as SemanticEntry[];
    }
    return this.db.prepare("SELECT * FROM semantic ORDER BY updated_at DESC LIMIT ?")
      .all(limit) as unknown as SemanticEntry[];
  }

  /**
   * Search facts by relevance to a query.
   *
   * Two paths, chosen by the query's script:
   *
   * - Latin queries use FTS5 BM25.
   * - Queries containing CJK use substring scoring over the fact table. FTS5
   *   ships no CJK segmenter, so a run of Chinese characters is indexed as ONE
   *   token: `术语` matches 0 rows in a store whose value contains it, and no
   *   phrase query recovers an interior substring. Substring scoring is the
   *   only option that needs no segmentation dependency, and the table is
   *   small enough (thousands of rows at most) that a scan is cheaper than
   *   the workarounds.
   */
  searchSemantic(query: string, limit: number = 10): SemanticEntry[] {
    const terms = queryTerms(query);
    if (terms.length === 0) return [];

    if (terms.some(containsCjk)) return this._searchSemanticSubstring(terms, limit);
    if (!this.hasFTS5) return this._searchSemanticSubstring(terms, limit);

    // Build FTS5 query — quote each term for safety
    const ftsQuery = terms.map(t => `"${t.replace(/"/g, '""')}"`).join(" OR ");

    try {
      const rows = this.db.prepare(`
        SELECT s.key, s.value, s.confidence, s.source, s.session_id, s.created_at, s.updated_at, s.last_accessed
        FROM semantic s
        JOIN semantic_fts fts ON s.rowid = fts.rowid
        WHERE semantic_fts MATCH ?
        ORDER BY bm25(semantic_fts)
        LIMIT ?
      `).all(ftsQuery, limit) as unknown as SemanticEntry[];

      if (rows.length > 0) return rows;
      return this._searchSemanticSubstring(terms, limit);
    } catch {
      // FTS query failed — fall back to substring matching
      return this._searchSemanticSubstring(terms, limit);
    }
  }

  private _searchSemanticSubstring(terms: string[], limit: number): SemanticEntry[] {
    const all = this.db.prepare("SELECT * FROM semantic").all() as unknown as SemanticEntry[];
    const scored: Array<{ entry: SemanticEntry; score: number; hits: number }> = [];

    for (const entry of all) {
      const text = `${entry.key} ${entry.value}`.toLowerCase();
      let matched = 0;
      let hits = 0;
      for (const term of terms) {
        const n = countOccurrences(text, term);
        if (n > 0) {
          matched++;
          hits += n;
        }
      }
      if (matched === 0) continue;
      // Coverage first (how much of the query this fact answers), then
      // repetition as a weak tiebreak so a fact that is *about* the term
      // outranks one that mentions it in passing.
      scored.push({ entry, score: matched / terms.length, hits });
    }

    scored.sort((a, b) => b.score - a.score || b.hits - a.hits);
    return scored.slice(0, limit).map(s => s.entry);
  }

  /**
   * Record that these facts were injected. One statement for the whole set:
   * the previous per-key loop issued a write per fact per turn, and this runs
   * on every turn.
   */
  touchAccessed(keys: string[]): void {
    if (keys.length === 0) return;
    const placeholders = keys.map(() => "?").join(",");
    this.db.prepare(
      `UPDATE semantic SET last_accessed = datetime('now') WHERE key IN (${placeholders})`
    ).run(...keys.map(k => k.toLowerCase()));
  }

  // ─── Lessons ─────────────────────────────────────────────────────

  addLesson(rule: string, category: string = "general", source: string = "consolidation", negative: boolean = false, project?: string): { success: boolean; id?: string; reason?: string } {
    const trimmed = rule.trim();
    if (!trimmed) return { success: false, reason: "empty rule" };

    const normalizedCategory = category.trim().toLowerCase() || "general";

    return this.withLock(() => {
      // Exact-match dedup (case-insensitive)
      const existing = this.db.prepare(
        "SELECT id FROM lessons WHERE LOWER(TRIM(rule)) = LOWER(?) AND is_deleted = 0"
      ).get(trimmed.toLowerCase()) as { id: string } | undefined;
      if (existing) return { success: false as const, reason: "duplicate" as const, id: existing.id };

      // Jaccard dedup
      const allRules = this.db.prepare("SELECT id, rule FROM lessons WHERE is_deleted = 0").all() as { id: string; rule: string }[];
      for (const r of allRules) {
        if (jaccard(trimmed, r.rule) >= 0.7) {
          return { success: false as const, reason: "similar" as const, id: r.id };
        }
      }

      const id = crypto.randomUUID();
      this.db.prepare(
        "INSERT INTO lessons (id, rule, category, source, negative, project) VALUES (?, ?, ?, ?, ?, ?)"
      ).run(id, trimmed, normalizedCategory, source, negative ? 1 : 0, project ?? null);

      this.logEvent("create", "lesson", id, trimmed.slice(0, 100));
      return { success: true as const, id };
    });
  }

  getLesson(id: string): LessonEntry | undefined {
    const row = this.db.prepare("SELECT * FROM lessons WHERE id = ? AND is_deleted = 0").get(id) as any;
    if (!row) return undefined;
    return { ...row, negative: !!row.negative };
  }

  /**
   * List lessons, optionally filtered by category and/or project.
   *
   * Project filtering:
   * - If `project` is provided, returns lessons where `project = slug` OR `project IS NULL`
   *   (NULL = user-authored or pre-migration lessons, treated as global).
   * - If `project` is not provided, returns all lessons (no project filter).
   */
  listLessons(category?: string, limit: number = 50, project?: string): LessonEntry[] {
    let rows: any[];
    if (category && project) {
      const normalizedCategory = category.trim().toLowerCase();
      rows = this.db.prepare(
        "SELECT * FROM lessons WHERE category = ? AND (project = ? OR project IS NULL) AND is_deleted = 0 ORDER BY created_at DESC LIMIT ?"
      ).all(normalizedCategory, project, limit);
    } else if (category) {
      const normalizedCategory = category.trim().toLowerCase();
      rows = this.db.prepare("SELECT * FROM lessons WHERE category = ? AND is_deleted = 0 ORDER BY created_at DESC LIMIT ?")
        .all(normalizedCategory, limit);
    } else if (project) {
      rows = this.db.prepare(
        "SELECT * FROM lessons WHERE (project = ? OR project IS NULL) AND is_deleted = 0 ORDER BY created_at DESC LIMIT ?"
      ).all(project, limit);
    } else {
      rows = this.db.prepare("SELECT * FROM lessons WHERE is_deleted = 0 ORDER BY created_at DESC LIMIT ?")
        .all(limit);
    }
    return rows.map(r => ({ ...r, negative: !!r.negative, project: r.project ?? null }));
  }

  /**
   * Search lessons by relevance to a query. Same script-based split as
   * searchSemantic: FTS5 cannot match an interior CJK substring.
   */
  searchLessons(query: string, limit: number = 20): LessonEntry[] {
    const terms = queryTerms(query);
    if (terms.length === 0) return [];

    if (terms.some(containsCjk)) return this._searchLessonsSubstring(terms, limit);
    if (!this.hasFTS5) return this._searchLessonsSubstring(terms, limit);

    const ftsQuery = terms.map(t => `"${t.replace(/"/g, '""')}"`).join(" OR ");

    try {
      const rows = this.db.prepare(`
        SELECT l.id, l.rule, l.category, l.source, l.negative, l.created_at, l.project
        FROM lessons l
        JOIN lessons_fts fts ON l.rowid = fts.rowid
        WHERE lessons_fts MATCH ? AND l.is_deleted = 0
        ORDER BY bm25(lessons_fts)
        LIMIT ?
      `).all(ftsQuery, limit) as any[];

      const mapped = rows.map(r => ({ ...r, negative: !!r.negative, project: r.project ?? null }));

      if (mapped.length > 0) return mapped;
      return this._searchLessonsSubstring(terms, limit);
    } catch {
      return this._searchLessonsSubstring(terms, limit);
    }
  }

  private _searchLessonsSubstring(terms: string[], limit: number): LessonEntry[] {
    const all = this.db.prepare("SELECT * FROM lessons WHERE is_deleted = 0").all() as any[];
    const scored: Array<{ entry: LessonEntry; score: number; hits: number }> = [];

    for (const entry of all) {
      const text = `${entry.rule} ${entry.category}`.toLowerCase();
      let matched = 0;
      let hits = 0;
      for (const term of terms) {
        const n = countOccurrences(text, term);
        if (n > 0) {
          matched++;
          hits += n;
        }
      }
      if (matched === 0) continue;
      scored.push({
        entry: { ...entry, negative: !!entry.negative, project: entry.project ?? null } as LessonEntry,
        score: matched / terms.length,
        hits,
      });
    }

    scored.sort((a, b) => b.score - a.score || b.hits - a.hits);
    return scored.slice(0, limit).map(s => s.entry);
  }

  deleteLesson(id: string): boolean {
    return this.withLock(() => {
      // Support both full UUIDs and prefix matches (e.g. first 8 chars)
      let result = this.db.prepare("UPDATE lessons SET is_deleted = 1 WHERE id = ? AND is_deleted = 0").run(id);
      if (result.changes === 0 && id.length < 36) {
        // Try prefix match — ensure it's unambiguous
        const matches = this.db.prepare("SELECT id FROM lessons WHERE id LIKE ? AND is_deleted = 0").all(`${id}%`) as { id: string }[];
        if (matches.length === 1) {
          result = this.db.prepare("UPDATE lessons SET is_deleted = 1 WHERE id = ? AND is_deleted = 0").run(matches[0].id);
          if (result.changes > 0) this.logEvent("delete", "lesson", matches[0].id);
          return true;
        }
      }
      if (result.changes > 0) this.logEvent("delete", "lesson", id);
      return result.changes > 0;
    });
  }

  // ─── Events ──────────────────────────────────────────────────────

  private logEvent(eventType: string, memoryType: string, key: string, details: string = ""): void {
    this.db.prepare(
      "INSERT INTO events (event_type, memory_type, memory_key, details) VALUES (?, ?, ?, ?)"
    ).run(eventType, memoryType, key, details);
  }

  listEvents(limit: number = 50): MemoryEvent[] {
    return this.db.prepare("SELECT * FROM events ORDER BY id DESC LIMIT ?").all(limit) as unknown as MemoryEvent[];
  }

  // ─── Pending consolidation (outbox) ───────────────────────────────

  /**
   * Queue a session tail for later consolidation.
   *
   * One commit: ~13 ms at synchronous=NORMAL, against the several seconds a
   * consolidation run costs. That is the whole point — the expensive part
   * must not run while the user is waiting to quit or switch sessions.
   *
   * Tails supersede each other instead of conflicting: a resumed session
   * re-seeds its whole history, so a new tail that carries at least as many
   * messages replaces the older unclaimed ones (the queue cannot grow one
   * duplicate job per run). A *smaller* tail is new information — it only
   * exists after a drain cleared the buffer — so it is queued alongside; two
   * surviving rows are two genuinely unconsumed tails, not a duplicate. A
   * claimed row is mid-flight and is never touched.
   */
  enqueuePending(sessionId: string | undefined, payload: unknown, userCount: number): void {
    const json = JSON.stringify(payload);
    const key = sessionId ?? null;
    this.withLock(() => {
      this.db
        .prepare(
          `DELETE FROM pending_consolidation
           WHERE session_id IS ? AND claimed_at IS NULL AND user_count <= ?`,
        )
        .run(key, userCount);
      this.db
        .prepare("INSERT INTO pending_consolidation (session_id, user_count, payload) VALUES (?, ?, ?)")
        .run(key, userCount, json);
      this.db.prepare(
        `DELETE FROM pending_consolidation WHERE id NOT IN
           (SELECT id FROM pending_consolidation ORDER BY id DESC LIMIT 20)`,
      ).run();
    });
  }

  /**
   * Take the oldest queued job, marking it claimed so a concurrent drainer
   * skips it. A job whose claim is older than `staleAfterMinutes` is offered
   * again: a drainer that was killed mid-run must not lose the work.
   */
  claimPending(staleAfterMinutes: number = 10): { id: number; payload: string } | undefined {
    return this.withLock(() => {
      const row = this.db
        .prepare(
          `SELECT id, payload FROM pending_consolidation
           WHERE claimed_at IS NULL OR claimed_at < datetime('now', ?)
           ORDER BY id LIMIT 1`,
        )
        .get(`-${staleAfterMinutes} minutes`) as { id: number; payload: string } | undefined;
      if (!row) return undefined;
      this.db
        .prepare("UPDATE pending_consolidation SET claimed_at = datetime('now') WHERE id = ?")
        .run(row.id);
      return row;
    });
  }

  /** Drop a job after its facts were written — at-least-once, never silent loss. */
  deletePending(id: number): void {
    this.withLock(() => {
      this.db.prepare("DELETE FROM pending_consolidation WHERE id = ?").run(id);
    });
  }

  /**
   * Hand a claimed job back to the queue. Used when a drain is interrupted by
   * shutdown: without it the job would sit claimed until the stale window
   * expires, so a user who quits mid-consolidation would see a dead queue.
   */
  releasePending(id: number): void {
    this.withLock(() => {
      this.db.prepare("UPDATE pending_consolidation SET claimed_at = NULL WHERE id = ?").run(id);
    });
  }

  /**
   * Record a failed attempt and requeue the job. Returns the new attempt count,
   * so the caller can decide when to stop retrying a prompt that keeps failing.
   */
  failPending(id: number): number {
    return this.withLock(() => {
      this.db
        .prepare("UPDATE pending_consolidation SET attempts = attempts + 1, claimed_at = NULL WHERE id = ?")
        .run(id);
      const row = this.db.prepare("SELECT attempts FROM pending_consolidation WHERE id = ?").get(id) as
        | { attempts: number }
        | undefined;
      return row?.attempts ?? 0;
    });
  }

  /**
   * Run `fn` with a short busy timeout.
   *
   * node:sqlite is synchronous, so `BEGIN IMMEDIATE` against a lock held by
   * another process blocks *this* process's event loop for up to busy_timeout —
   * i.e. a background write can freeze the TUI for seconds. Background work
   * should yield instead and let the queue retry it.
   */
  withBusyTimeout<T>(ms: number, fn: () => T): T {
    const previous = (this.db.prepare("PRAGMA busy_timeout").get() as { timeout: number }).timeout;
    this.db.exec(`PRAGMA busy_timeout = ${Math.max(0, Math.floor(ms))}`);
    try {
      return fn();
    } finally {
      this.db.exec(`PRAGMA busy_timeout = ${previous}`);
    }
  }

  pendingCount(): number {
    return (this.db.prepare("SELECT COUNT(*) AS c FROM pending_consolidation").get() as { c: number }).c;
  }

  // ─── Stats ───────────────────────────────────────────────────────

  stats(): { semantic: number; lessons: number; events: number; pending: number } {
    const semantic = (this.db.prepare("SELECT COUNT(*) as c FROM semantic").get() as any).c;
    const lessons = (this.db.prepare("SELECT COUNT(*) as c FROM lessons WHERE is_deleted = 0").get() as any).c;
    const events = (this.db.prepare("SELECT COUNT(*) as c FROM events").get() as any).c;
    return { semantic, lessons, events, pending: this.pendingCount() };
  }

  close(): void {
    this.db.close();
  }
}

// ─── Helpers ─────────────────────────────────────────────────────────

/** Any CJK, Japanese kana, or Hangul codepoint. */
const CJK_RE = /[\u3040-\u30ff\u3400-\u4dbf\u4e00-\u9fff\uf900-\ufaff\uac00-\ud7af]/;

export function containsCjk(s: string): boolean {
  return CJK_RE.test(s);
}

/**
 * Split a query into searchable terms.
 *
 * Latin text splits on non-word characters. CJK runs split into overlapping
 * BIGRAMS: a whole run is never matched by anything but itself (see
 * searchSemantic), and single CJK characters are too common to rank on. So
 * `网关 key 配置` yields `网关`, `key`, `配置`.
 */
export function queryTerms(query: string): string[] {
  const terms = new Set<string>();

  for (const word of query.toLowerCase().split(/[^\p{L}\p{N}_]+/u)) {
    if (!word) continue;
    if (!containsCjk(word)) {
      terms.add(word);
      continue;
    }
    const chars = Array.from(word);
    if (chars.length === 1) {
      terms.add(chars[0]!);
      continue;
    }
    for (let i = 0; i < chars.length - 1; i++) terms.add(chars[i]! + chars[i + 1]!);
  }

  // Single latin characters ("a", "i") are noise; a single CJK character is a
  // word and stays.
  return [...terms].filter(t => t.length > 1 || containsCjk(t));
}

/** Non-overlapping occurrences of `needle` in `haystack`. */
function countOccurrences(haystack: string, needle: string): number {
  if (!needle) return 0;
  let count = 0;
  let at = haystack.indexOf(needle);
  while (at !== -1) {
    count++;
    at = haystack.indexOf(needle, at + needle.length);
  }
  return count;
}

function jaccard(a: string, b: string): number {
  const setA = new Set(a.toLowerCase().split(/\s+/).filter(Boolean));
  const setB = new Set(b.toLowerCase().split(/\s+/).filter(Boolean));
  if (setA.size === 0 && setB.size === 0) return 1;
  const intersection = new Set([...setA].filter(x => setB.has(x)));
  const union = new Set([...setA, ...setB]);
  return intersection.size / union.size;
}
